#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  TOTAL_STAGES=8
  cd "$(dirname "${BASH_SOURCE[0]}")/.."
  [[ "$ENV_FILE" == '.env' ]] || { warn "This Compose wizard writes only the repository .env file."; return 1; }
  umask 077
  [[ ! -L "$ENV_FILE" ]] || { warn "Refusing a symlink for the environment file."; return 1; }
  [[ ! -e "$ENV_FILE" || -f "$ENV_FILE" ]] || return 1
  touch "$ENV_FILE"
  chmod 600 "$ENV_FILE"

  save() {
    case "$2" in *"'"*|*$'\n'*|*$'\r'*) warn "Use a value without quotes or line breaks."; return 1;; esac
    write_env "$1" "$2"
  }
  random_secret() { node -e 'process.stdout.write(require("node:crypto").randomBytes(32).toString("hex"))'; }
  preserve_secret() {
    local value
    value=$(_existing "$1" || true)
    [[ -n "$value" ]] || value=$(random_secret)
    save "$1" "$value"
  }
  banner "SpecVoice local setup"

  stage "Host prerequisites"
  command -v node >/dev/null && command -v docker >/dev/null
  [[ -d node_modules ]] || { warn "Run npm ci first."; return 1; }
  docker version --format '{{.Server.Version}}' | node -e '
    let s=""; process.stdin.on("data", x=>s+=x).on("end",()=>{
      if(Number(s.split(".")[0])<28) { console.error("Docker Engine 28+ required for isolated bridge networking"); process.exit(1); }
    })'
  docker compose version
  say "Docker must have capacity for a 2-CPU, 4-GiB Build plus PostgreSQL and the application."
  note "Only Compose is configured here. Existing credentials stay local in the mode-0600 .env file."
  pause

  stage "Private dashboard and operator login"
  if [[ -z "$(_existing SPECVOICE_OPERATOR_PASSWORD_HASH || true)" ]] || confirm "Replace the operator passphrase and revoke old logins?"; then
    ask_secret OPERATOR_PASSPHRASE "Choose a unique operator passphrase (at least 16 characters):"
    [[ ${#OPERATOR_PASSPHRASE} -ge 16 ]] || { warn "Passphrase is too short."; return 1; }
    ask_secret OPERATOR_REPEAT "Repeat the passphrase:"
    [[ "$OPERATOR_PASSPHRASE" == "$OPERATOR_REPEAT" ]] || { warn "Passphrases differ."; return 1; }
    local password_hash
    password_hash=$(printf '%s' "$OPERATOR_PASSPHRASE" | node --import tsx -e '
      let value=""; process.stdin.on("data", x=>value+=x).on("end",async()=>{
        const {hashOperatorPassphrase}=require("./src/lib/security/operator.ts");
        process.stdout.write(await hashOperatorPassphrase(value));
      })')
    save SPECVOICE_OPERATOR_PASSWORD_HASH "$password_hash"
    unset OPERATOR_PASSPHRASE OPERATOR_REPEAT password_hash
  fi
  preserve_secret SESSION_CAPABILITY_SECRET
  preserve_secret SPECVOICE_SERVICE_SECRET
  if [[ -z "$(_existing POSTGRES_PASSWORD || true)" ]]; then
    local project existing_volumes
    project="${COMPOSE_PROJECT_NAME:-$(_existing COMPOSE_PROJECT_NAME || basename "$PWD" | tr '[:upper:]' '[:lower:]')}"
    existing_volumes=$(docker volume ls --filter "label=com.docker.compose.project=$project" --filter 'label=com.docker.compose.volume=specvoice-postgres' --format '{{.Name}}')
    if [[ -n "$existing_volumes" ]]; then
      warn "An existing Compose database volume was found. Its password is not changed by editing .env."
      ask_secret POSTGRES_PASSWORD "Enter its existing database password (older default: specvoice-local):"
      [[ -n "$POSTGRES_PASSWORD" ]] || return 1
      save POSTGRES_PASSWORD "$POSTGRES_PASSWORD"
    fi
  fi
  preserve_secret POSTGRES_PASSWORD
  [[ "$POSTGRES_PASSWORD" =~ ^[A-Za-z0-9_-]+$ ]] || { warn "Existing PostgreSQL password is not URL-safe; configure an encoded connection URL before proceeding."; return 1; }
  save POSTGRES_USER "$(_existing POSTGRES_USER || echo specvoice)"
  save POSTGRES_DB "$(_existing POSTGRES_DB || echo specvoice)"
  save SPECVOICE_OPERATOR_ORIGIN "$(_existing SPECVOICE_OPERATOR_ORIGIN || echo http://localhost:3000)"
  note "Dashboard: localhost:3000. Keep it private; expose only provider ingress on localhost:3001."
  pause

  stage "Provider credentials"
  open_url 'https://elevenlabs.io/docs/overview/administration/workspaces/api-keys'
  step "Create an ElevenLabs key in your workspace. Limit its permissions to your agent setup, conversations and testing."
  ask_secret ELEVENLABS_API_KEY "Paste the ElevenLabs key (blank defers voice setup):"
  save ELEVENLABS_API_KEY "$ELEVENLABS_API_KEY"
  open_url 'https://platform.claude.com/settings/keys'
  step "Create an Anthropic API key for the model gateway. Set provider-side spending limits too."
  ask_secret ANTHROPIC_API_KEY "Paste the Anthropic key (blank defers Builds):"
  save ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
  note "The execution container receives only an attempt credential, never this real model key."

  stage "GitHub and disposable acceptance repository"
  open_url 'https://github.com/settings/personal-access-tokens/new'
  step "Select only the repositories SpecVoice may use. Read token: Contents read. Build token: Contents and Pull requests write."
  ask_secret GITHUB_READ_TOKEN "Paste the read-only GitHub token:"
  ask_secret GITHUB_TOKEN "Paste the Build publication token:"
  save GITHUB_READ_TOKEN "$GITHUB_READ_TOKEN"
  save GITHUB_TOKEN "$GITHUB_TOKEN"
  open_url 'https://github.com/new'
  step "Create a dedicated disposable repository with synthetic Node/npm code, a lockfile, and an explicit test script."
  ask SPECVOICE_LIVE_TEST_REPO "Its HTTPS GitHub URL (blank defers live acceptance):"
  if [[ -n "$SPECVOICE_LIVE_TEST_REPO" ]]; then
    [[ "$SPECVOICE_LIVE_TEST_REPO" =~ ^https://github.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]] || return 1
  fi
  save SPECVOICE_LIVE_TEST_REPO "$SPECVOICE_LIVE_TEST_REPO"

  stage "Private agent and signed callbacks"
  open_url 'https://elevenlabs.io/docs/eleven-agents/customization/authentication'
  step "Route your HTTPS tunnel or reverse proxy ONLY to localhost:3001, never the dashboard port."
  ask NEXT_PUBLIC_APP_URL "Public HTTPS provider-ingress URL (blank defers provider setup):"
  if [[ -n "$NEXT_PUBLIC_APP_URL" ]]; then
    [[ "$NEXT_PUBLIC_APP_URL" == https://* && "$NEXT_PUBLIC_APP_URL" != *'?'* && "$NEXT_PUBLIC_APP_URL" != *'#'* ]] || return 1
    save NEXT_PUBLIC_APP_URL "${NEXT_PUBLIC_APP_URL%/}"
  fi
  note "After saving keys and URL, npm run setup:agent creates/updates the private agent and prints its ID."
  if [[ -n "$ELEVENLABS_API_KEY" && -n "$NEXT_PUBLIC_APP_URL" ]] && confirm "Create or update the ElevenLabs agent and its tools now?"; then
    ELEVENLABS_API_KEY="$ELEVENLABS_API_KEY" \
      ELEVENLABS_AGENT_ID="$(_existing ELEVENLABS_AGENT_ID || true)" \
      NEXT_PUBLIC_APP_URL="$NEXT_PUBLIC_APP_URL" npm run setup:agent
  fi
  ask ELEVENLABS_AGENT_ID "Agent ID (blank defers voice setup):"
  save ELEVENLABS_AGENT_ID "$ELEVENLABS_AGENT_ID"
  open_url 'https://elevenlabs.io/app/agents/settings'
  step "Configure the post-call webhook as PUBLIC_URL/api/agent/post-call. Enable HMAC authentication and copy the signing secret."
  ask_secret ELEVENLABS_WEBHOOK_SECRET "Webhook HMAC signing secret:"
  save ELEVENLABS_WEBHOOK_SECRET "$ELEVENLABS_WEBHOOK_SECRET"
  note "Keep agent authentication enabled in its Security settings. Call capabilities are created at call start."

  stage "External backup destination"
  local backup_enabled=false
  if confirm "Configure a mounted second disk or NAS now?"; then
    ask SPECVOICE_BACKUP_DESTINATION "Absolute path of an existing dedicated backup directory:"
    [[ "$SPECVOICE_BACKUP_DESTINATION" == /* && -d "$SPECVOICE_BACKUP_DESTINATION" && ! -L "$SPECVOICE_BACKUP_DESTINATION" ]] || return 1
    SPECVOICE_BACKUP_DESTINATION=$(cd "$SPECVOICE_BACKUP_DESTINATION" && pwd -P)
    say "A different path does not prove a different physical disk. Confirm this mount survives loss of the application disk."
    confirm "Is this a mounted independent disk/NAS, and may SpecVoice create its volume marker and repository here?" || return 1
    local marker="$SPECVOICE_BACKUP_DESTINATION/.specvoice-backup-volume"
    [[ ! -L "$marker" ]] || return 1
    if [[ -e "$marker" ]]; then
      SPECVOICE_BACKUP_VOLUME_ID=$(cat "$marker")
      [[ "$SPECVOICE_BACKUP_VOLUME_ID" =~ ^[a-f0-9]{64}$ ]] || return 1
    else
      SPECVOICE_BACKUP_VOLUME_ID=$(random_secret)
      printf '%s\n' "$SPECVOICE_BACKUP_VOLUME_ID" > "$marker"
    fi
    save SPECVOICE_BACKUP_DESTINATION "$SPECVOICE_BACKUP_DESTINATION"
    save SPECVOICE_BACKUP_VOLUME_ID "$SPECVOICE_BACKUP_VOLUME_ID"
    save SPECVOICE_BACKUP_UID "$(id -u)"
    save SPECVOICE_BACKUP_GID "$(id -g)"
    backup_enabled=true
  else SKIPPED+=("Independent-disk backup setup and restore drill"); fi

  stage "Separately recoverable backup password"
  if $backup_enabled; then
    ask SPECVOICE_BACKUP_PASSWORD_FILE "Absolute local recovery-password file path, outside the backup destination:"
    [[ "$SPECVOICE_BACKUP_PASSWORD_FILE" == /* && ! -L "$SPECVOICE_BACKUP_PASSWORD_FILE" ]] || return 1
    local key_parent
    key_parent=$(cd "$(dirname "$SPECVOICE_BACKUP_PASSWORD_FILE")" && pwd -P)
    SPECVOICE_BACKUP_PASSWORD_FILE="$key_parent/$(basename "$SPECVOICE_BACKUP_PASSWORD_FILE")"
    [[ "$SPECVOICE_BACKUP_PASSWORD_FILE" != "$SPECVOICE_BACKUP_DESTINATION"/* ]] || return 1
    [[ "$SPECVOICE_BACKUP_PASSWORD_FILE" != "$PWD"/* ]] || { warn "Keep the recovery password outside the source repository."; return 1; }
    if [[ ! -e "$SPECVOICE_BACKUP_PASSWORD_FILE" ]]; then
      ask_secret RECOVERY_PASSWORD "Choose a recovery password (at least 24 characters):"
      [[ ${#RECOVERY_PASSWORD} -ge 24 ]] || return 1
      ask_secret RECOVERY_REPEAT "Repeat recovery password:"
      [[ "$RECOVERY_PASSWORD" == "$RECOVERY_REPEAT" ]] || return 1
      printf '%s\n' "$RECOVERY_PASSWORD" > "$SPECVOICE_BACKUP_PASSWORD_FILE"
      unset RECOVERY_PASSWORD RECOVERY_REPEAT
    fi
    [[ -s "$SPECVOICE_BACKUP_PASSWORD_FILE" && -f "$SPECVOICE_BACKUP_PASSWORD_FILE" ]] || return 1
    chmod 600 "$SPECVOICE_BACKUP_PASSWORD_FILE"
    save SPECVOICE_BACKUP_PASSWORD_FILE "$SPECVOICE_BACKUP_PASSWORD_FILE"
    confirm "Have you saved a separate recovery copy outside this host and backup disk?" || return 1
    note "Follow docs/backups.md: explicit init, daily scheduler, then restore drill. Existing repositories are never reinitialized."
  else note "Backup recovery remains unverified until this setup and its external restore drill are complete."; fi

  stage "Optional nightly evaluations and live acceptance"
  save SPECVOICE_LIVE_BUDGET_USD '10'
  say "Read docs/evaluation.md before paid checks. Initial voice + Build acceptance has a US$10 estimated total budget."
  ask SPECVOICE_LIVE_EVAL_ESTIMATE_USD "Conservative USD estimate for the synthetic evaluation suite, from your provider plan (blank disables paid evaluations):"
  if [[ -n "$SPECVOICE_LIVE_EVAL_ESTIMATE_USD" ]]; then
    [[ "$SPECVOICE_LIVE_EVAL_ESTIMATE_USD" =~ ^(0|[1-9][0-9]*)(\.[0-9]{1,6})?$ ]] || return 1
    node -e 'const n=Number(process.argv[1]); if(!(n>0 && n<=10)) process.exit(1)' "$SPECVOICE_LIVE_EVAL_ESTIMATE_USD" || { warn "Estimate must be above zero and at most US$10."; return 1; }
  fi
  save SPECVOICE_LIVE_EVAL_ESTIMATE_USD "$SPECVOICE_LIVE_EVAL_ESTIMATE_USD"
  if confirm "Copy ElevenLabs credentials to this repository's GitHub Actions secrets for nightly paid evaluations?"; then
    [[ -n "$ELEVENLABS_API_KEY" && -n "$ELEVENLABS_AGENT_ID" && -n "$SPECVOICE_LIVE_EVAL_ESTIMATE_USD" ]] || return 1
    set_secret ELEVENLABS_API_KEY "$ELEVENLABS_API_KEY"
    set_secret ELEVENLABS_AGENT_ID "$ELEVENLABS_AGENT_ID"
    set_var SPECVOICE_LIVE_EVAL_ESTIMATE_USD "$SPECVOICE_LIVE_EVAL_ESTIMATE_USD"
  fi
  SKIPPED+=("Live voice/build acceptance and real destination restore drill: runbooks in docs/evaluation.md and docs/backups.md")
  finish
  say "Start: docker compose up --build -d"
  say "Private dashboard: http://localhost:3000"
  say "Status: docker compose exec worker npm run ops:status"
}

run_wizard "$@"; exit
